head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


fixedX = -1; ////////// 레이어 X축 위치 (-1 : 버튼에 바로 아래에 표시)
fixedY = -1; ////////////// 레이어 Y축 위치 (-1 : 버튼에 바로 아래에 표시)
startAt = 0; ///////////// 일요일 표시 부분 / 0 : 일요일(일월화...) / 1 : 월요일(...금토일)
showToday = 1; // 오늘 날자 표시 유무 - 0 : 감춤 / 1 : 보임
imgDir = './'; // 이미지 디렉토리 - ./ : 현재 디렉토리

/////////////////////////////// 각 변수 선언 ///////////////////
crossobj, scwin.crossMonthObj, scwin.crossYearObj, scwin.monthSelected, scwin.yearSelected, scwin.dateSelected, scwin.omonthSelected, scwin.oyearSelected, scwin.odateSelected, scwin.monthConstructed, scwin.yearConstructed, scwin.intervalID1, scwin.intervalID2, scwin.timeoutID1, scwin.timeoutID2, scwin.ctlToPlaceValue, scwin.ctlNow, scwin.dateFormat, scwin.nStartingMonth, scwin.nStartingYear;
bPageLoaded = false;
ie = document.all;
dom = document.getElementById;
bShow = false;
ns4 = document.layers;
today = new Date(); /////////////// 날자 변수 선언
dateNow = today.getDate(); //////////////// 로컬 컴퓨터의 일(day)을 구함
monthNow = today.getMonth(); ///////////////// 로컬 컴퓨터의 월(month)을 구함
yearNow = today.getYear(); ///////////////// 로컬 컴퓨터의 년(year)을 구함

monthName = new Array("1월", "2월", "3월", "4월", "5월", "6월", "7월", "8월", "9월", "10월", "11월", "12월");
monthName2 = new Array("1월", "2월", "3월", "4월", "5월", "6월", "7월", "8월", "9월", "10월", "11월", "12월");
if (scwin.startAt == 0) {
    dayName = new Array("일", "월", "화", "수", "목", "금", "토");
} else {
    dayName = new Array("월", "화", "수", "목", "금", "토", "일");
}
oPopup = window.createPopup();
oPopBody = oPopup.document.body;
strCalendar;
cleft;
ctop;
gridType = "N"; //aa
pColid; //aa
pRow; //aa

//코스닥 벌점부과 화면이라면 날짜 선택 이후 체크로직 수행하도록
isPNLT = false;
// 1: 벌점(제제금)부과일 선택, 2:지정유예결정일 선택
gubunPNLT = 0;
afterCallType = false;
if (scwin.dom) {
    scwin.strCalendar = "<img src='' width=0 height=0>";
    scwin.strCalendar += "<style type='text/css'>";
    scwin.strCalendar += "td {font-size__12px; font-family:돋움; text-decoration:none; }";
    scwin.strCalendar += "A:link,A:active,A:visited{text-decoration:none;font-size__12PX;color:#333333;}";
    scwin.strCalendar += "A:hover {text-decoration:none; color:ff9900}";
    scwin.strCalendar += "font { font-size: 9pt; }";
    scwin.strCalendar += ".cnj_close {font-size__8pt; color:#000000; background-color:#EFEFEF; border-width:1; border-color:#808080; border-style__solid;cursor:hand;font-weight:bold;height:16px;width:16px;text-align:center;vertical-align:bottom}";
    scwin.strCalendar += ".cnj_close2 {font-size__8pt; color:#000000; background-color:#EFEFEF; border-width:1; border-color:#808080; border-style__solid;cursor:hand;font-weight:bold;height:16px;width:16px;text-align:center;vertical-align:bottom}";
    scwin.strCalendar += ".cnj_input {background-color:rgb(240,240,240);border-width:1pt; height:16pt;cursor:hand;}";
    scwin.strCalendar += ".cnj_input2 {font-size__8pt;color:#808080; background-color:#EFEFEF; border-width:1; border-color:#808080; border-style__solid;cursor:hand;height:16px;}";
    scwin.strCalendar += ".cnj_input3 {font-size__8pt;color:#000000; background-color:#FFFFFF; border-width:1; border-color:#C00000; border-style__solid;cursor:hand;height:16px;}";
    scwin.strCalendar += ".cnj_input4 {font-size__8pt;color:#C00000; background-color:#FFFFFF; border-width:1; border-color:#808080; border-style__solid;cursor:hand;height:16px;}";
    scwin.strCalendar += ".cnj_td {border-width:1;border-style__solid;border-color:#a0a0a0;}";
    scwin.strCalendar += "</style>";
    scwin.strCalendar += "<div id='calendar' style='z-index:+999;position:absolute;;'>";
    scwin.strCalendar += "<table width='190' class='cnj_td'>";
    scwin.strCalendar += "	<tr bgcolor='#EEEEEE' height=20>";
    scwin.strCalendar += "		<td>";
    scwin.strCalendar += "			<table width='188' border=0>";
    scwin.strCalendar += "				<tr height=20>";
    scwin.strCalendar += "					<td style='padding:0px;'><font color='#ffffff'><B><span id='caption'></span></B></font></td>";
    scwin.strCalendar += "					<td align=right><input type='button' value='x' class='cnj_close' title='닫기' onclick='parent.oPopup.hide()' onfocus='this.blur()' onMouseover=\"this.className='cnj_close2'\" onMouseout=\"this.className='cnj_close'\"></td>";
    scwin.strCalendar += "				</tr>";
    scwin.strCalendar += "			</table>";
    scwin.strCalendar += "		</td>";
    scwin.strCalendar += "	</tr>";
    scwin.strCalendar += "	<tr height=1>";
    scwin.strCalendar += "		<td style='padding:3px' bgcolor=#ffffff><span id='content'></span></td>";
    scwin.strCalendar += "	</tr>";
    if (scwin.showToday == 1) {
        scwin.strCalendar += "<tr bgcolor=#f0f0f0 height=20><td style='padding:5px' align=center><span id='lblToday'></span></td></tr>";
    }
    scwin.strCalendar += "</table>";
    scwin.strCalendar += "</div>";
    scwin.strCalendar += "<div id='selectMonth' style='z-index:+999;position:absolute;display:none;'></div> ";
    scwin.strCalendar += "<div id='selectYear' style='z-index:+999;position:absolute;display:none;'></div>";
    oPopBody.innerHTML = scwin.strCalendar;
}
/**
 * @method
 * @name init
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.init = function() {
    if (!scwin.ns4) {
        if (!scwin.ie) {
            scwin.yearNow += 1900;
        }
        scwin.crossobj = oPopBody.all.calendar;
        scwin.crossMonthObj = oPopBody.all.selectMonth;
        scwin.crossYearObj = oPopBody.all.selectYear;
        scwin.monthConstructed = false;
        scwin.yearConstructed = false;
        if (scwin.showToday == 1) {
            oPopup.document.getElementById("lblToday").innerHTML = "" + "<div onmousemove='window.status=\"오늘 날짜로 표시하기\"' onmouseout='window.status=\"\"' title='오늘 날짜로 표시하기' " + " style='" + scwin.styleAnchor + "' href='javascript:monthSelected=monthNow;yearSelected=yearNow;constructCalendar();' onFocus='this.blur()'>" + "오늘 날짜 :  " + scwin.yearNow + "년 " + "" + monthName[monthNow].substring(0, 3) + " " + "" + scwin.dateNow + "일 " + // 일
                "</div>";
        }
        sHTML1 = "<input type='button' value='◀' class='cnj_input2' onClick='javascript:parent.movedecMonth()' onfocus='this.blur()' title='이전 달(월)로 이동' ";
        sHTML1 += "onMouseover=\"this.className='cnj_input3';window.status='이전 달(월)로 이동'\" onMouseout=\"this.className='cnj_input2';window.status=''\"> </span> ";
        sHTML1 += "<input type='button' value='▶'  class='cnj_input2' onClick='javascript:parent.moveincMonth()' onfocus='this.blur()' title='다음 달(월)로 이동' ";
        sHTML1 += "onMouseover=\"this.className='cnj_input3';window.status='다음 달(월)로 이동'\"  onMouseout=\"this.className='cnj_input2';window.status=''\"> </span> ";
        sHTML1 += "<span id='spanMonth'  class='cnj_input4' onclick='parent.popUpMonth()' title='월 선택' ";
        sHTML1 += "onMouseover=\"this.className='cnj_input3';window.status='월 선택'\" onMouseout=\"this.className='cnj_input4';window.status=''\"></span>&nbsp;";
        sHTML1 += "<span id='spanYear'  class='cnj_input4' onclick='parent.popUpYear()' title='년도 선택' ";
        sHTML1 += "onMouseover=\"this.className='cnj_input3';window.status='년도 선택'\" onMouseout=\"this.className='cnj_input4';window.status=''\"></span> ";
        oPopup.document.getElementById("caption").innerHTML = sHTML1;
        scwin.bPageLoaded = true;
    }
};
/**
 * @method
 * @name HolidayRec
 * @description desc
 * @param {string} d desc
 * @param {string} m desc
 * @param {string} y desc
 * @param {string} desc desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.HolidayRec = function(d, m, y, desc) {
    this.d = d;
    this.m = m;
    this.y = y;
    this.desc = desc;
};
HolidaysCounter = 0;
Holidays = new Array();
/**
 * @method
 * @name addHoliday
 * @description desc
 * @param {string} d desc
 * @param {string} m desc
 * @param {string} y desc
 * @param {string} desc desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addHoliday = function(d, m, y, desc) {
    Holidays[scwin.HolidaysCounter++] = new HolidayRec(d, m, y, desc);
};
styleAnchor = "text-decoration:none;color:black;cursor:hand;width:100%;height:100%";
styleLightBorder = "border-style__solid;border-width:1px;border-color:#a0a0a0;text-decoration:underline;font-weight:bold;cursor:hand;width:100%;height:100%";
/**
 * @method
 * @name padZero
 * @description desc
 * @param {string} num desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.padZero = function(num) {
    return (num < 10) ? '0' + num : num;
};
/**
 * @method
 * @name constructDate
 * @description desc
 * @param {string} d desc
 * @param {string} m desc
 * @param {string} y desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.constructDate = function(d, m, y) {
    sTmp = scwin.dateFormat;
    sTmp = sTmp.replace("dd", "<e>");
    sTmp = sTmp.replace("d", "<d>");
    sTmp = sTmp.replace("<e>", scwin.padZero(d));
    sTmp = sTmp.replace("<d>", d);
    sTmp = sTmp.replace("mmmm", "<p>");
    sTmp = sTmp.replace("mmm", "<o>");
    sTmp = sTmp.replace("mm", "<n>");
    sTmp = sTmp.replace("m", "<m>");
    sTmp = sTmp.replace("<m>", m + 1);
    sTmp = sTmp.replace("<n>", scwin.padZero(m + 1));
    sTmp = sTmp.replace("<o>", monthName[m]);
    sTmp = sTmp.replace("<p>", monthName2[m]);
    sTmp = sTmp.replace("yyyy", y);
    return sTmp.replace("yy", scwin.padZero(y % 100));
};

//aa
/**
 * @method
 * @name closeCalendar
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.closeCalendar = function() {
    oPopup.hide();
    if (scwin.gridType == "Y") {
        ctlToPlaceValue.setCellData(scwin.pRow, scwin.pColid, scwin.constructDate(scwin.dateSelected, scwin.monthSelected, scwin.yearSelected));
    } else {
        eval(scwin.ctlToPlaceValue).setValue(scwin.constructDate(scwin.dateSelected, scwin.monthSelected, scwin.yearSelected));
    }
    if (scwin.isPNLT) {
        //dsclmgt/ULDSTF35109.gfm & ULDSTF35119.gfm에 있음
        checkGraceInfo(scwin.gubunPNLT);
        scwin.isPNLT = false;
    }
    //시작일(edt_SDate) 종료일(edt_EDate) 비교
    if (scwin.afterCallType) {
        scwin.afterPopUpCalendar(scwin.gubunPNLT);
        scwin.afterCallType = false;
    }
};
/**
 * @method
 * @name moveincMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.moveincMonth = function() {
    scwin.monthSelected++;
    if (scwin.monthSelected > 11) {
        scwin.monthSelected = 0;
        scwin.yearSelected++;
    }
    scwin.constructCalendar();
};
/**
 * @method
 * @name movedecMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.movedecMonth = function() {
    scwin.monthSelected--;
    if (scwin.monthSelected < 0) {
        scwin.monthSelected = 11;
        scwin.yearSelected--;
    }
    scwin.constructCalendar();
};
/**
 * @method
 * @name incMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.incMonth = function() {
    if (scwin.nStartingMonth + 6 == 12) return;
    for (i = 0; i < 7; i++) {
        newMonth = (i + scwin.nStartingMonth) + 1;
        if (newMonth > 12) {
            scwin.nStartingMonth--;
            break;
        }
        if (newMonth == scwin.monthSelected + 1) {
            txtMonth = " <B>" + newMonth + "월</B> ";
        } else {
            txtMonth = " " + newMonth + "월";
        }
        oPopup.document.getElementById("m" + i).innerHTML = txtMonth;
    }
    scwin.nStartingMonth++;
    scwin.bShow = true;
};
/**
 * @method
 * @name decMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.decMonth = function() {
    if (scwin.nStartingMonth == 1) return;
    for (i = 0; i < 7; i++) {
        newMonth = (i + scwin.nStartingMonth) - 1;
        if (newMonth < 1) {
            scwin.nStartingMonth++;
            break;
        }
        if (newMonth == scwin.monthSelected + 1) {
            txtMonth = " <B>" + newMonth + "월</B> ";
        } else {
            txtMonth = " " + newMonth + "월";
        }
        oPopup.document.getElementById("m" + i).innerHTML = txtMonth;
    }
    scwin.nStartingMonth--;
    scwin.bShow = true;
};
/**
 * @method
 * @name selectMonth
 * @description desc
 * @param {string} nMonth desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.selectMonth = function(nMonth) {
    scwin.monthSelected = parseInt(nMonth + scwin.nStartingMonth - 1);
    scwin.monthConstructed = false;
    scwin.constructCalendar();
    scwin.popDownMonth();
};
/**
 * @method
 * @name constructMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.constructMonth = function() {
    scwin.popDownYear();
    sHTML = "";
    if (!scwin.monthConstructed) {
        // 월 이전 월 링크
        sHTML = "<tr><td align='center' style='cursor:pointer'	 ";
        sHTML += "	onmouseover='this.style.backgroundColor=\"#FFCC99\"' ";
        sHTML += "	onmouseout='clearInterval(parent.intervalID1);this.style.backgroundColor=\"\"'  ";
        sHTML += "	onmousedown='clearInterval(parent.intervalID1);parent.intervalID1=setInterval(\"parent.decMonth()\",30)' ";
        sHTML += "	onmouseup='clearInterval(parent.intervalID1)'> ";
        sHTML += "	▲</td></tr>";
        j = 0;
        var nSelectedMonth = scwin.monthSelected + 1;
        scwin.nStartingMonth = (nSelectedMonth - 3) < 1 ? 1 : nSelectedMonth - 3; //시작월 - 3 이 1보다 작으면 1로 고정
        scwin.nStartingMonth = scwin.nStartingMonth > 6 ? 6 : scwin.nStartingMonth; //시작월이 6보다 크면 6로 고정 (6 시작 월 + 목록 숫자 6 = 12 종료 월)

        var nEndMonth = (nSelectedMonth + 3) > 12 ? 12 : (nSelectedMonth + 3); // 종료월 + 3이 12보다 크면 12로 고정
        nEndMonth = nEndMonth < 7 ? 7 : nEndMonth; //종료 월이 7보다 작으면 7로 고정

        for (i = scwin.nStartingMonth; i <= nEndMonth; i++) {
            sName = i;

            //////////////// 현재 월 ////////////////////////
            if (i == nSelectedMonth) {
                sName = "<b>" + sName + "</b>";
            }
            sHTML += "<tr><td height='15' id='m" + j + "' onmouseover='this.style.backgroundColor=\"#FFCC99\"' onmouseout='this.style.backgroundColor=\"\"' ";
            sHTML += " style='cursor:pointer' onClick='parent.selectMonth(" + j + ");event.cancelBubble=true'> " + sName + "월";
            sHTML += "</td></tr>";
            j++;
        }

        // 월 다음 월 링크
        sHTML += "<tr><td align='center' onmouseover='this.style.backgroundColor=\"#FFCC99\"' style='cursor:pointer' ";
        sHTML += " onmouseout='clearInterval(parent.intervalID2);this.style.backgroundColor=\"\"' ";
        sHTML += " onmousedown='clearInterval(parent.intervalID2);parent.intervalID2=setInterval(\"parent.incMonth()\",30)'	";
        sHTML += " onmouseup='clearInterval(parent.intervalID2)'> ";
        sHTML += " ▼</td></tr>";

        /////// 월 표 크기 ///////////////////////////////
        oPopup.document.getElementById("selectMonth").innerHTML = "" + "<table width='50' style='font-family:굴림; font-size__11px; border-width:1; border-style__solid; border-color:#a0a0a0;' bgcolor='#FFFFDD' " + " onmouseover='clearTimeout(parent.timeoutID2)' " + " onmouseout='clearTimeout(parent.timeoutID2);parent.timeoutID2=setTimeout(\"parent.popDownMonth()\",100)' cellspacing=0>" + "" + sHTML + "" + "</table>";
        scwin.monthConstructed = true;
    }
};
/**
 * @method
 * @name popUpMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.popUpMonth = function() {
    scwin.constructMonth();
    crossMonthObj.style.display = "";
    crossMonthObj.style.left = crossobj.style.left + 50;
    crossMonthObj.style.top = crossobj.style.top + 26;
};
/**
 * @method
 * @name popDownMonth
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.popDownMonth = function() {
    crossMonthObj.style.display = "none";
};
/**
 * @method
 * @name incYear
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.incYear = function() {
    for (i = 0; i < 7; i++) {
        newYear = (i + scwin.nStartingYear) + 1;
        if (newYear == scwin.yearSelected) {
            txtYear = " <B>" + newYear + "년  </B> ";
        } else {
            txtYear = " " + newYear + "년  ";
        }
        oPopup.document.getElementById("y" + i).innerHTML = txtYear;
    }
    scwin.nStartingYear++;
    scwin.bShow = true;
};
/**
 * @method
 * @name decYear
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.decYear = function() {
    for (i = 0; i < 7; i++) {
        newYear = (i + scwin.nStartingYear) - 1;
        if (newYear == scwin.yearSelected) {
            txtYear = " <B>" + newYear + "년  </B> ";
        } else {
            txtYear = " " + newYear + "년  ";
        }
        oPopup.document.getElementById("y" + i).innerHTML = txtYear;
    }
    scwin.nStartingYear--;
    scwin.bShow = true;
};
/**
 * @method
 * @name selectYear
 * @description desc
 * @param {string} nYear desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.selectYear = function(nYear) {
    scwin.yearSelected = parseInt(nYear + scwin.nStartingYear);
    scwin.yearConstructed = false;
    scwin.constructCalendar();
    scwin.popDownYear();
};
/**
 * @method
 * @name constructYear
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.constructYear = function() {
    scwin.popDownMonth();
    sHTML = "";
    if (!scwin.yearConstructed) {
        // 년도 이전 년도 링크
        sHTML = "<tr><td align='center' style='cursor:pointer'	 ";
        sHTML += "	onmouseover='this.style.backgroundColor=\"#FFCC99\"' ";
        sHTML += "	onmouseout='clearInterval(parent.intervalID1);this.style.backgroundColor=\"\"'  ";
        sHTML += "	onmousedown='clearInterval(parent.intervalID1);parent.intervalID1=setInterval(\"parent.decYear()\",30)' ";
        sHTML += "	onmouseup='clearInterval(parent.intervalID1)'> ";
        sHTML += "	▲</td></tr>";
        j = 0;
        scwin.nStartingYear = scwin.yearSelected - 3;
        for (i = (scwin.yearSelected - 3); i <= (scwin.yearSelected + 3); i++) {
            sName = i;
            if (i == scwin.yearSelected) {
                sName = "<b>" + sName + "</b>";
            }
            sHTML += "<tr><td height='15' id='y" + j + "' onmouseover='this.style.backgroundColor=\"#FFCC99\"' onmouseout='this.style.backgroundColor=\"\"' ";
            sHTML += " style='cursor:pointer' onClick='parent.selectYear(" + j + ");event.cancelBubble=true'> " + sName + "년  ";
            sHTML += "</td></tr>";
            j++;
        }

        // 년도 다음 년도 링크
        sHTML += "<tr><td align='center' onmouseover='this.style.backgroundColor=\"#FFCC99\"' style='cursor:pointer' ";
        sHTML += " onmouseout='clearInterval(parent.intervalID2);this.style.backgroundColor=\"\"' ";
        sHTML += " onmousedown='clearInterval(parent.intervalID2);parent.intervalID2=setInterval(\"parent.incYear()\",30)'	";
        sHTML += " onmouseup='clearInterval(parent.intervalID2)'> ";
        sHTML += " ▼</td></tr>";

        /////// 년도 표 크기 ///////////////////////////////
        oPopup.document.getElementById("selectYear").innerHTML = "" + "<table width='55' style='font-family:굴림; font-size__11px; border-width:1; border-style__solid; border-color:#a0a0a0;' bgcolor='#FFFFDD' " + " onmouseover='clearTimeout(parent.timeoutID2)' " + " onmouseout='clearTimeout(parent.timeoutID2);parent.timeoutID2=setTimeout(\"parent.popDownYear()\",100)' cellspacing=0>" + "" + sHTML + "" + "</table>";
        scwin.yearConstructed = true;
    }
};
/**
 * @method
 * @name popDownYear
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.popDownYear = function() {
    clearInterval(scwin.intervalID1);
    clearTimeout(scwin.timeoutID1);
    clearInterval(scwin.intervalID2);
    clearTimeout(scwin.timeoutID2);
    crossYearObj.style.display = "none";
};
/**
 * @method
 * @name popUpYear
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.popUpYear = function() {
    scwin.constructYear();
    crossYearObj.style.display = "";
    crossYearObj.style.left = crossobj.style.left + (6 + oPopup.document.getElementById("spanYear").offsetLeft) + "px";
    crossYearObj.style.top = crossobj.style.top + 26;
};
/**
 * @method
 * @name constructCalendar
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.constructCalendar = function() {
    var aNumDays = new Array(31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);
    var dateMessage;
    var startDate = new Date(scwin.yearSelected, scwin.monthSelected, 1);
    var endDate;
    var intWeekCount = 1;
    if (scwin.monthSelected == 1) {
        endDate = new Date(scwin.yearSelected, scwin.monthSelected + 1, 1);
        endDate = new Date(endDate - (24 * 60 * 60 * 1000));
        numDaysInMonth = endDate.getDate();
    } else {
        numDaysInMonth = aNumDays[monthSelected];
    }
    datePointer = 0;
    dayPointer = startDate.getDay() - scwin.startAt;
    if (dayPointer < 0) {
        dayPointer = 6;
    }
    sHTML = "<table	 border=0 style='font-family:verdana;font-size__10px;'><tr height=16>";
    for (i = 0; i < 7; i++) {
        /////// 요일 ///////////////////////
        sHTML += "<td width='27' align='right'><B>" + dayName[i] + "</B></td>";
    }
    sHTML += "</tr><tr height=16>";
    for (var i = 1; i <= dayPointer; i++) {
        // 빈 날짜
        sHTML += "<td> </td>";
    }
    for (datePointer = 1; datePointer <= numDaysInMonth; datePointer++) {
        dayPointer++;
        sHTML += "<td align=right>";
        sStyle = scwin.styleAnchor;
        if ((datePointer == scwin.odateSelected) && (scwin.monthSelected == scwin.omonthSelected) && (scwin.yearSelected == scwin.oyearSelected)) {
            sStyle += scwin.styleLightBorder;
        }
        sHint = "";
        for (k = 0; k < scwin.HolidaysCounter; k++) {
            if ((parseInt(Holidays[k].d) == datePointer) && (parseInt(Holidays[k].m) == (scwin.monthSelected + 1))) {
                if ((parseInt(Holidays[k].y) == 0) || ((parseInt(Holidays[k].y) == scwin.yearSelected) && (parseInt(Holidays[k].y) != 0))) {
                    sStyle += "background-color:#FFDDDD;";
                    sHint += sHint == "" ? Holidays[k].desc : "\n" + Holidays[k].desc;
                }
            }
        }
        var regexp = /\"/g;
        sHint = sHint.replace(regexp, "&quot;");
        /////////////// 날짜 선택시 ==> 마우스가 날짜 위로 갔을때 ///////////////////////////////
        dateMessage = "title=' 날짜 선택 : " + scwin.yearSelected + "년 " + monthName[monthSelected] + " " + datePointer + "일" + "' onmousemove='window.status=\" 날짜 선택 : " + scwin.yearSelected + "년 " + monthName[monthSelected] + " " + datePointer + "일" + "\"' onmouseout='window.status=\"\"' ";
        if ((datePointer == scwin.dateNow) && (scwin.monthSelected == scwin.monthNow) && (scwin.yearSelected == scwin.yearNow)) {
            // 현재 오늘 날짜
            sHTML += "<b><div style='" + sStyle + "' onclick='javascript:parent.dateSelected=" + datePointer + ";parent.closeCalendar();'><font color=#0000C0> " + datePointer + "</font> </div></b>";
        } else if (dayPointer % 7 == (scwin.startAt * -1) + 1) {
            // 일요일 일때
            sHTML += "<div style='" + sStyle + "' onclick='javascript:parent.dateSelected=" + datePointer + ";parent.closeCalendar();'> <font color=red>" + datePointer + "</font> </div>";
        } else {
            sHTML += "<div style='" + sStyle + "' onclick='javascript:parent.dateSelected=" + datePointer + ";parent.closeCalendar();'>" + datePointer + "</div>";
        }
        sHTML += "";
        if ((dayPointer + scwin.startAt) % 7 == scwin.startAt) {
            sHTML += "</tr><tr height=16>";
            intWeekCount++;
        }
    }
    sHTML += "</tr>";
    sHTML = sHTML.replace("<tr height=16></tr>", "");
    if (((dayPointer + scwin.startAt) % 7) == 0) intWeekCount--;
    oPopup.document.getElementById("content").innerHTML = sHTML;
    //////// 셀릭트 월 선택
    oPopup.document.getElementById("spanMonth").innerHTML = " " + monthName[monthSelected] + " <input type='button'  id='changeMonth'value='▼'  class='cnj_input2' onfocus='this.blur()' onMouseover=\"this.className='cnj_input3'\" onMouseout=\"this.className='cnj_input2'\">";

    //////// 셀릭트 년도 선택
    oPopup.document.getElementById("spanYear").innerHTML = " " + scwin.yearSelected + "년 <input type='button'  id='changeYear'' value='▼'  class='cnj_input2' onfocus='this.blur()' onMouseover=\"this.className='cnj_input3'\" onMouseout=\"this.className='cnj_input2'\">";

    //alert(intWeekCount);
    var popHeight;
    if (intWeekCount == 6) popHeight = 195;

    else popHeight = 177;
    oPopup.show(scwin.cleft, scwin.ctop, 198, popHeight, document.body);
};
/**
 * @method
 * @name popUpCalendar
 * @description desc
 * @param {string} ctl desc
 * @param {string} ctl2 desc
 * @param {string} format desc
 * @param {string} isScroll desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.popUpCalendar = function(ctl, ctl2, format, isScroll) {
    scwin.gridType = "N";
    var leftpos = 0;
    var toppos = 0;
    var aData = new Array();
    if (scwin.bPageLoaded) {
        scwin.ctlToPlaceValue = ctl2;
        scwin.dateFormat = format;
        formatChar = "-";
        aFormat = dateFormat.replace(/(^\s*)|(\s*$)/g, "");
        if (aFormat.length == 10) {
            aFormat = dateFormat.split(formatChar);
        } else {
            formatChar = "";
        }
        if (aFormat.length < 3) {

        }
        tokensChanged = '0';
        if (formatChar != "") {
            insertdata = eval(ctl2).getText();
            aData[0] = insertdata.substr(0, 4);
            aData[1] = insertdata.substr(4, 2);
            aData[2] = insertdata.substr(6, 2);
            for (i = 0; i < 3; i++) {
                if ((aFormat[i] == "d") || (aFormat[i] == "dd")) {
                    scwin.dateSelected = parseInt(aData[i], 10);
                    tokensChanged++;
                } else if ((aFormat[i] == "m") || (aFormat[i] == "mm")) {
                    scwin.monthSelected = parseInt(aData[i], 10) - 1;
                    tokensChanged++;
                } else if (aFormat[i] == "yyyy") {
                    scwin.yearSelected = parseInt(aData[i], 10);
                    tokensChanged++;
                } else if (aFormat[i] == "mmm") {
                    for (j = 0; j < 12; j++) {
                        if (aData[i] == monthName[j]) {
                            scwin.monthSelected = j;
                            tokensChanged++;
                        }
                    }
                } else if (aFormat[i] == "mmmm") {
                    for (j = 0; j < 12; j++) {
                        if (aData[i] == monthName2[j]) {
                            scwin.monthSelected = j;
                            tokensChanged++;
                        }
                    }
                }
            }
        }
        if ((tokensChanged != 3) || isNaN(scwin.dateSelected) || isNaN(scwin.monthSelected) || isNaN(scwin.yearSelected)) {
            scwin.dateSelected = scwin.dateNow;
            scwin.monthSelected = scwin.monthNow;
            scwin.yearSelected = scwin.yearNow;
        }
        scwin.odateSelected = scwin.dateSelected;
        scwin.omonthSelected = scwin.monthSelected;
        scwin.oyearSelected = scwin.yearSelected;
        aTag = ctl;
        do {
            aTag = aTag.offsetParent;
            leftpos += aTag.offsetLeft;
            toppos += aTag.offsetTop;
        } while (aTag.tagName != "BODY");
        if (isScroll) toppos = toppos - document.body.scrollTop;
        scwin.cleft = scwin.fixedX == -1 ? ctl.offsetLeft + leftpos : scwin.fixedX;
        scwin.ctop = scwin.fixedY == -1 ? ctl.offsetTop + ctl.offsetHeight + toppos : scwin.fixedY;
        scwin.constructCalendar(1, scwin.monthSelected, scwin.yearSelected);
        scwin.bShow = true;
        scwin.ctlNow = ctl;
    }
};




