/**
 * @method
 * @name mid
 * @description desc
 * @param {string} str desc
 * @param {string} idx desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.mid = function(str, idx) {
    return str.substring(0, str.length - idx);
};
/**
 * @method
 * @name toDaySet
 * @description desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.toDaySet = function(sval) {
    //
    var m2 = (scwin.monthNow + 1) + "";
    if (m2.length == 1) {
        m2 = "0" + m2;
    }
    var d2 = scwin.dateNow + "";
    if (d2.length == 1) {
        d2 = "0" + d2;
    }
    sval.setValue(scwin.yearNow + "" + m2 + "" + d2);
};


