//달력선택 후 호출
/**
 * @method
 * @name afterPopUpCalendar
 * @description desc
 * @param {string} c desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.afterPopUpCalendar = function(c) {
    var s_date = $c.stf.getObjectValue(edt_SDate);
    var e_date = $c.stf.getObjectValue(edt_EDate);
    if (c == 2) {
        if (s_date > e_date) {
            $c.stf.setObjectValue(edt_SDate, e_date);
        }
    } else {
        if (s_date > e_date) {
            $c.stf.setObjectValue(edt_EDate, s_date);
        }
    }
};
